def preserve_existing_versions(apps, schema_editor):
    """在调整资料前冻结旧内容；反向迁移需以备份恢复新版本记录。"""
    database = schema_editor.connection.alias
    history = apps.get_model('cultivation', 'DefinitionRevision')
    ingredients = apps.get_model('cultivation', 'RecipeIngredient')
    categories = {'Realm': 'realms', 'Item': 'items', 'Art': 'arts',
                  'PlaceType': 'place-types', 'FacilityType': 'facility-types', 'Recipe': 'recipes'}
    for name, category in categories.items():
        model = apps.get_model('cultivation', name)
        for row in model.objects.using(database).all():
            content = {'category': category}
            for field in row._meta.concrete_fields:
                if field.name in {'id', 'revision', 'content_hash'}:
                    continue
                value = getattr(row, field.name)
                content_field = 'typical_realm' if field.name == 'minimum_realm' and name in {'Art', 'Item'} else field.name
                content[content_field] = value.key if field.is_relation and value is not None else value
            if name == 'Recipe':
                pairs = ingredients.objects.using(database).filter(recipe_id=row.pk).values_list('item__key', 'quantity')
                content['ingredients'] = [{'item': key, 'quantity': quantity} for key, quantity in sorted(pairs)]
            digest = hashlib.sha256(json.dumps(content, ensure_ascii=False, sort_keys=True,
                                               separators=(',', ':')).encode('utf-8')).hexdigest()
            model.objects.using(database).filter(pk=row.pk).update(content_hash=digest)
            history.objects.using(database).create(category=category, definition_key=row.key,
                                                   revision=row.revision, content_hash=digest, content=content)


